    "{threadLabel} · {tabs} onglet · dernière action {value2}",
  "Recent agent actions": "Actions récentes des agents",
  "Quit {name} to import": "Quittez {name} pour importer",
  "{name} is open, so its cookies can’t be read yet. Quit it, then continue.":
    "{name} est ouvert, ses cookies ne peuvent donc pas encore être lus. Quittez-le, puis continuez.",
  "I’ve quit it": "Je l'ai quitté",
  "Let SpecWithCode read {name}’s cookies": "Autoriser SpecWithCode à lire les cookies de {name}",
  "To import cookies from {name}, SpecWithCode needs Full Disk Access. Turn it on in System Settings, then come back to finish the import — you can revoke it again once the import is done.":
    "Pour importer les cookies de {name}, SpecWithCode a besoin de l'accès complet au disque. Activez-le dans Réglages Système, puis revenez terminer l'importation ; vous pourrez le révoquer une fois l'importation terminée.",
  "Access is still required. Quit and reopen SpecWithCode if you just allowed it, then retry the import.":
    "L'accès est toujours nécessaire. Si vous venez de l'autoriser, quittez et rouvrez SpecWithCode, puis relancez l'importation.",
  "If access doesn't update after you allow it, quit and reopen SpecWithCode, then retry the import.":
    "Si l'accès ne se met pas à jour après l'avoir autorisé, quittez et rouvrez SpecWithCode, puis relancez l'importation.",
