  "This connection can create access links but cannot view authorized clients.":
    "Cette connexion peut créer des liens d'accès mais ne peut pas voir les clients autorisés.",
  "Enable network access?": "Activer l'accès réseau ?",
  "Disable network access?": "Désactiver l'accès réseau ?",
  "Let your other devices connect to SpecWithCode over your local network. This mode uses plain HTTP, so its traffic is not encrypted: anyone on the same network can capture the sign-in and use it to control the app. Turn it on only on a network you trust, and use SpecWithCode Connect or Tailscale HTTPS for remote access. Pair devices to give them access. The app will restart.":
    "Permettez à vos autres appareils de se connecter à SpecWithCode via votre réseau local. Ce mode utilise du HTTP simple, son trafic n'est donc pas chiffré : toute personne sur le même réseau peut intercepter la connexion et s'en servir pour contrôler l'app. Activez-le seulement sur un réseau de confiance et utilisez SpecWithCode Connect ou Tailscale HTTPS pour l'accès à distance. Associez des appareils pour leur donner accès. L'app va redémarrer.",
  "Devices connected over your local network will disconnect. Existing tunnels, such as SpecWithCode Connect or Tailscale HTTPS, keep working. SpecWithCode will restart.":
    "Les appareils connectés via votre réseau local seront déconnectés. Les tunnels existants, comme SpecWithCode Connect ou Tailscale HTTPS, continuent de fonctionner. SpecWithCode va redémarrer.",
  "Restarting…": "Redémarrage…",
  "Restart and enable": "Redémarrer et activer",
  "Restart and disable": "Redémarrer et désactiver",
