  "Disable WSL backend?": "Désactiver le backend WSL ?",
  "Switch WSL distro?": "Changer de distribution WSL ?",
  "Start the WSL backend": "Démarrer le backend WSL",
  "Run only the WSL backend?": "Exécuter uniquement le backend WSL ?",
  "Re-enable the Windows backend?": "Réactiver le backend Windows ?",
  "SpecWithCode will restart on the Windows backend. Threads and projects opened against WSL stay safe inside the distro and become available again when you re-enable WSL.":
    "SpecWithCode va redémarrer sur le backend Windows. Les fils et projets ouverts dans WSL restent en sécurité dans la distribution et redeviennent disponibles quand vous réactivez WSL.",
  "The WSL backend will stop. Threads and projects opened against WSL stay safe inside the distro, but they'll be unavailable in SpecWithCode until you re-enable WSL.":
    "Le backend WSL va s'arrêter. Les fils et projets ouverts dans WSL restent en sécurité dans la distribution, mais seront indisponibles dans SpecWithCode jusqu'à ce que vous réactiviez WSL.",
  "SpecWithCode will restart the WSL backend on the new distro. Sessions still running on the current distro will be interrupted.":
    "SpecWithCode va redémarrer le backend WSL sur la nouvelle distribution. Les sessions encore en cours sur la distribution actuelle seront interrompues.",
  "Run the WSL backend alongside the Windows one, or stop the Windows backend and use only WSL? You can change this later from Settings.":
    "Exécuter le backend WSL à côté de celui de Windows, ou arrêter le backend Windows et n'utiliser que WSL ? Vous pourrez changer cela plus tard dans les Paramètres.",
  "SpecWithCode will restart and start only the WSL backend. Your Windows-side projects won't be accessible until you turn this off again.":
    "SpecWithCode va redémarrer et ne lancer que le backend WSL. Vos projets côté Windows ne seront pas accessibles tant que vous n'aurez pas désactivé cette option.",
  "SpecWithCode will restart and bring the Windows backend back up alongside WSL.":
    "SpecWithCode va redémarrer et relancer le backend Windows à côté de WSL.",
  "Applying…": "Application…",
  "Use only WSL": "Utiliser uniquement WSL",
  "Run both backends": "Exécuter les deux backends",
  "Disable WSL": "Désactiver WSL",
  "Switch distro": "Changer de distribution",
  "Disable Tailscale HTTPS?": "Désactiver Tailscale HTTPS ?",
  "SpecWithCode will restart the local backend without Tailscale Serve.":
    "SpecWithCode va redémarrer le backend local sans Tailscale Serve.",
  "Tailscale will stop serving HTTPS for the SpecWithCode service on this computer.":
    "Tailscale cessera de servir HTTPS pour le service SpecWithCode sur cet ordinateur.",
  "Set up Tailscale HTTPS?": "Configurer Tailscale HTTPS ?",
  "SpecWithCode will restart the local backend with Tailscale Serve enabled and ask Tailscale to proxy HTTPS traffic to this backend.":
    "SpecWithCode va redémarrer le backend local avec Tailscale Serve activé et demander à Tailscale de relayer le trafic HTTPS vers ce backend.",
  "Tailscale will serve HTTPS on your tailnet and forward it to the SpecWithCode service on this computer.":
    "Tailscale servira HTTPS sur votre tailnet et le transmettra au service SpecWithCode sur cet ordinateur.",
