  "No custom options. The composer uses the provider's default options.":
    "Aucune option personnalisée. Le compositeur utilise les options par défaut du fournisseur.",
  "Custom option": "Option personnalisée",
  "Jev, from TypeSafe, picks one option from a fixed list in well under a second and costs almost nothing. When the coordinator does not say whether a task is complex or routine, Jev picks the lane, and it settles the kind of work when the keyword rules are unsure. The coordinator can also ask it any multiple-choice question. If Jev is slow or unreachable, routing keeps the rules' answer.":
    "Jev, de TypeSafe, choisit une option dans une liste fixe en bien moins d'une seconde et ne coûte presque rien. Quand le coordinateur ne dit pas si une tâche est complexe ou routinière, Jev choisit la voie, et il tranche le type de travail quand les règles par mots-clés hésitent. Le coordinateur peut aussi lui poser n'importe quelle question à choix multiple. Si Jev est lent ou injoignable, le routage garde la réponse des règles.",
  "Decision model provider": "Fournisseur du modèle de décision",
  "Jev answers once a key is saved. Create one at {a}. It stays in this machine's secret store and is only sent to {label}.":
    "Jev répond une fois une clé enregistrée. Créez-en une sur {a}. Elle reste dans le coffre de secrets de cette machine et n'est envoyée qu'à {label}.",
