  "The SpecWithCode service this app is connected to (version {serverVersion}) is older than Google account support. Update that service to use it.":
    "Le service SpecWithCode auquel cette app est connectée (version {serverVersion}) est antérieur à la prise en charge des comptes Google. Mettez ce service à jour pour l'utiliser.",
  "Your own OAuth client": "Votre propre client OAuth",
  "{value}In Google Cloud Console, enable the Gmail, Google Calendar and Google Drive APIs, set up the consent screen, then create credentials of type {span} and application type {span2}. Paste its ID and secret here.":
    "{value}Dans Google Cloud Console, activez les API Gmail, Google Calendar et Google Drive, configurez l'écran de consentement, puis créez des identifiants de type {span} avec le type d'application {span2}. Collez ici son ID et son secret.",
