    "Connecté en tant que {span}. SpecWithCode peut lire {value}.",
  "your account": "votre compte",
  "Connect your Google account": "Connecter votre compte Google",
  "Pick what SpecWithCode may read. Gmail drafts lets your assistant save replies and send an exact copy only after you choose Send on its review card. The original draft stays in Gmail. Google asks you to confirm access in your browser.":
    "Choisissez ce que SpecWithCode peut lire. Les brouillons Gmail permettent à votre assistant d'enregistrer des réponses et d'en envoyer une copie exacte seulement après que vous avez choisi Envoyer sur sa carte de revue. Le brouillon d'origine reste dans Gmail. Google vous demande de confirmer l'accès dans votre navigateur.",
  "Connect Google": "Connecter Google",
  "Add another Google account": "Ajouter un autre compte Google",
  "If Google says it has not verified SpecWithCode yet, choose Advanced, then Go to SpecWithCode.":
    "Si Google indique qu'il n'a pas encore validé SpecWithCode, choisissez Paramètres avancés, puis Accéder à SpecWithCode.",
  "Finish in the {a}. This page updates when Google sends you back.":
    "Terminez dans l'{a}. Cette page se met à jour quand Google vous renvoie.",
  "Google sign-in tab": "onglet de connexion Google",
  "Google returns to {redirectUri}. If SpecWithCode runs on another machine, that page will not load: copy the address from the browser and paste it here.":
    "Google revient vers {redirectUri}. Si SpecWithCode tourne sur une autre machine, cette page ne se chargera pas : copiez l'adresse depuis le navigateur et collez-la ici.",
  "Address Google sent you to": "Adresse vers laquelle Google vous a envoyé",
  "Finish sign-in": "Terminer la connexion",
  "Projects that may read each account": "Projets autorisés à lire chaque compte",
  "Projects that may read it": "Projets autorisés à le lire",
  "Let Percy and the projects you choose read your Gmail, Calendar and Drive, so Percy can brief you on your day, find a document or check who is coming to a meeting.":
    "Laissez Percy et les projets de votre choix lire votre Gmail, Calendar et Drive, pour que Percy puisse vous résumer la journée, trouver un document ou vérifier qui vient à une réunion.",
  "Agents in a project see only the services you turn on for it.":
    "Les agents d'un projet ne voient que les services que vous activez pour lui.",
  "Agents use the default account unless asked for another, and may read every account turned on here.":
    "Les agents utilisent le compte par défaut sauf si on leur en demande un autre, et peuvent lire tous les comptes activés ici.",
