  "Seed from favorites": "Reprendre depuis les favoris",
  "hardest work": "travail le plus difficile",
  "learned preferences": "préférences apprises",
  "No learned model preferences yet. Rules are learned when you give feedback in chat, or can be recorded by the coordinator.":
    "Aucune préférence de modèle apprise pour l’instant. Les règles s’apprennent quand vous donnez votre avis dans la conversation, ou peuvent être enregistrées par le coordinateur.",
  "Feedback: “{note}”": "Avis : « {note} »",
  "Turn on": "Activer",
  "Review and approve": "Examiner et approuver",
  "Turn off": "Désactiver",
  "Draws its own commands and panes only.": "Dessine uniquement ses propres commandes et panneaux.",
  "Stopped with an error: {runtimeError}": "Arrêté avec une erreur : {runtimeError}",
  "Mods add commands, panes and status to the workbench. Each runs in a sandbox with no network, files or credentials, and only after you approve its exact contents. Any edit pauses it until you approve again.":
    "Les mods ajoutent des commandes, des panneaux et un état à l’atelier. Chacun s’exécute dans un bac à sable sans réseau, fichiers ni identifiants, et seulement après que vous avez approuvé son contenu exact. Toute modification le met en pause jusqu’à une nouvelle approbation.",
  "{value} {span}. Check a mod with {span2}.": "{value} {span}. Vérifiez un mod avec {span2}.",
  "Folder on this host:": "Dossier sur cet hôte :",
  "The SpecWithCode service this app is connected to{value} is older than Mods, so it has no mods to show. Update that service to list, approve and run mods.":
    "Le service SpecWithCode auquel l’app est connectée{value} est plus ancien que les Mods, il n’a donc aucun mod à afficher. Mettez ce service à jour pour lister, approuver et exécuter des mods.",
  "No mods on this host yet.": "Aucun mod sur cet hôte pour l’instant.",
  "Approve {name}?": "Approuver {name} ?",
  "Read the files in {value}/{name} first. This approves exactly the contents with this fingerprint; the CLI's validate command prints the same one.":
    "Lisez d’abord les fichiers dans {value}/{name}. Cela approuve exactement le contenu ayant cette empreinte ; la commande validate du CLI affiche la même.",
  "It asks for no permissions beyond drawing its own UI.":
    "Il ne demande aucune autorisation au-delà de dessiner sa propre interface.",
  "A mod can never answer approvals, grant folders, choose accounts or start a turn.":
    "Un mod ne peut jamais répondre aux approbations, accorder des dossiers, choisir des comptes ni lancer un tour.",
  Approve: "Approuver",
  "Send test": "Envoyer un test",
  "Connect notifications": "Connecter les notifications",
  "Project source": "Source du projet",
