  "No licenses match that search.": "Aucune licence ne correspond à cette recherche.",
  "Loading open-source notices…": "Chargement des mentions open source…",
  "Replay panel animation preview": "Rejouer l’aperçu de l’animation du panneau",
  "Turning on…": "Activation…",
  "This phone": "Ce téléphone",
  "Remove phone": "Retirer le téléphone",
  "Pair with a private QR code": "Associer avec un QR code privé",
  "Computer address · no pairing code": "Adresse de l’ordinateur · sans code d’appairage",
  "Copy computer address": "Copier l’adresse de l’ordinateur",
  "This window cannot create pairing codes. Reopen SpecWithCode with access to this computer.":
    "Cette fenêtre ne peut pas créer de codes d’appairage. Rouvrez SpecWithCode avec un accès à cet ordinateur.",
  "Ready to scan. The phone has not confirmed a connection yet.":
    "Prêt à scanner. Le téléphone n’a pas encore confirmé de connexion.",
  "This code expired. Generate a new code when your phone is ready.":
    "Ce code a expiré. Générez un nouveau code quand votre téléphone est prêt.",
  "The computer address changed. Generate a new code for this address.":
    "L’adresse de l’ordinateur a changé. Générez un nouveau code pour cette adresse.",
  "Set up Tailscale HTTPS": "Configurer Tailscale HTTPS",
  "Copy pairing link": "Copier le lien d’appairage",
  "Generate pairing code": "Générer un code d’appairage",
  "Generate new code": "Générer un nouveau code",
  "This is the entire report. It contains versions, diagnostic counts, and failure categories. Conversation content, raw logs, files, credentials, paths, and identifiers are excluded.":
    "Voici le rapport complet. Il contient des versions, des compteurs de diagnostic et des catégories d’échec. Le contenu des conversations, les journaux bruts, les fichiers, les identifiants de connexion, les chemins et les identifiants sont exclus.",
  "Diagnostics report preview": "Aperçu du rapport de diagnostic",
  "I reviewed this report": "J’ai examiné ce rapport",
  "I reviewed this report and want to save a copy.":
    "J’ai examiné ce rapport et je veux en enregistrer une copie.",
  "Save report": "Enregistrer le rapport",
  "The file is saved on your device. Share it with support only if you choose.":
    "Le fichier est enregistré sur votre appareil. Partagez-le avec le support seulement si vous le souhaitez.",
  "Data and privacy": "Données et confidentialité",
  "You control what you share.": "Vous contrôlez ce que vous partagez.",
  "Chat history, uploaded attachments, server settings, and diagnostic logs are stored on the environment you use. Provider logs and terminal output can contain conversation content or sensitive data.":
    "L’historique des conversations, les pièces jointes, les paramètres du serveur et les journaux de diagnostic sont stockés dans l’environnement que vous utilisez. Les journaux des fournisseurs et la sortie du terminal peuvent contenir le contenu des conversations ou des données sensibles.",
  "Drafts, preferences, and cached interface data can also remain on the device where you use the app, including with a remote environment. Drafts can contain prompts, attachment details, and selected terminal text.":
    "Les brouillons, les préférences et les données d’interface en cache peuvent aussi rester sur l’appareil où vous utilisez l’app, y compris avec un environnement distant. Les brouillons peuvent contenir des prompts, des détails de pièces jointes et du texte de terminal sélectionné.",
  "When you start an agent turn or use a connected service, the selected provider receives the context needed for that request under its own privacy policy.":
    "Quand vous lancez un tour d’agent ou utilisez un service connecté, le fournisseur choisi reçoit le contexte nécessaire à cette demande, selon sa propre politique de confidentialité.",
  "Send crash and error reports automatically":
    "Envoyer automatiquement les rapports de plantage et d'erreur",
  "On by default. Sends the app version, OS, architecture, failure category, provider and model when relevant, a sanitized error and stack with home paths removed, and a random install id. Never sends prompts, responses, files, tokens, or account or conversation ids. Setting STUDIO_CRASH_REPORTS=false on the server also turns it off.":
    "Activé par défaut. Envoie la version de l'app, le système, l'architecture, la catégorie d'échec, le fournisseur et le modèle si utile, une erreur et une pile nettoyées sans chemins personnels, et un identifiant d'installation aléatoire. N'envoie jamais de prompts, réponses, fichiers, jetons ni identifiants de compte ou de conversation. STUDIO_CRASH_REPORTS=false sur le serveur le désactive aussi.",
  "Turned off by STUDIO_CRASH_REPORTS or team rules on this server.":
    "Désactivé par STUDIO_CRASH_REPORTS ou les règles d'équipe sur ce serveur.",
  "Update this server to change crash report settings.":
    "Mets à jour ce serveur pour modifier les réglages des rapports de plantage.",
  "Product usage collection": "Collecte d’utilisation du produit",
  "Collection is off by default. If enabled by the server operator, usage events include provider and model choices, turn results, durations, and token totals. They exclude prompts, responses, and file contents.":
    "La collecte est désactivée par défaut. Si l’opérateur du serveur l’active, les événements d’utilisation incluent les choix de fournisseur et de modèle, les résultats des tours, les durées et les totaux de tokens. Ils excluent les prompts, les réponses et le contenu des fichiers.",
  "Local diagnostic collection helps troubleshoot problems. External trace, metric, and log export is separate from product usage collection and can be configured by the server operator.":
    "La collecte de diagnostics locale aide à résoudre les problèmes. L’export externe de traces, métriques et journaux est distinct de la collecte d’utilisation et peut être configuré par l’opérateur du serveur.",
  "Connect an environment to inspect its diagnostic export settings.":
    "Connectez un environnement pour inspecter ses paramètres d’export de diagnostics.",
  "Technical details": "Détails techniques",
  "There is no built-in analytics destination. Enabling collection requires STUDIO_TELEMETRY_ENABLED=true and a PostHog host and key on the server. To disable it, set STUDIO_TELEMETRY_ENABLED=false and restart the server. External OpenTelemetry export is configured separately. These indicators show startup settings, not confirmed delivery.":
    "Il n’y a pas de destination d’analyse intégrée. Activer la collecte nécessite STUDIO_TELEMETRY_ENABLED=true ainsi qu’un hôte et une clé PostHog sur le serveur. Pour la désactiver, définissez STUDIO_TELEMETRY_ENABLED=false et redémarrez le serveur. L’export OpenTelemetry externe se configure séparément. Ces indicateurs montrent les paramètres au démarrage, pas une livraison confirmée.",
  "Create a report from the selected environment, review every field, then save it if you want to share it. Creating a report does not upload it.":
    "Créez un rapport depuis l’environnement choisi, examinez chaque champ, puis enregistrez-le si vous voulez le partager. Créer un rapport ne l’envoie pas.",
  "Preparing report…": "Préparation du rapport…",
  "Preview diagnostic report": "Aperçu du rapport de diagnostic",
  "Could not prepare the report. Reconnect the environment and try again.":
    "Impossible de préparer le rapport. Reconnectez l’environnement et réessayez.",
