  "Linux worker guide": "guide des workers Linux",
  "Link SpecWithCode Connect here first, then make a line to paste on your main machine.":
    "Liez d’abord SpecWithCode Connect ici, puis créez une ligne à coller sur votre machine principale.",
  "Make a join line": "Créer une ligne d’adhésion",
  "Turn Auto off": "Désactiver Auto",
  "Long audio is transcribed first (speech to text), the transcript is split into chunks that fit the model's context, and the cheaper model works through the chunks. Auto never sends audio to a model that cannot hear it.":
    "Un long audio est d’abord transcrit (parole en texte), la transcription est découpée en morceaux qui tiennent dans le contexte du modèle, et le modèle le moins cher les traite un par un. Auto n’envoie jamais d’audio à un modèle qui ne peut pas l’entendre.",
  "A failure on the cheaper model gets one retry on the model the work would have used without Auto. Model changes happen only between turns.":
    "Un échec sur le modèle le moins cher donne droit à une nouvelle tentative sur le modèle que le travail aurait utilisé sans Auto. Les changements de modèle n’ont lieu qu’entre les tours.",
  "Routing conflicts": "Conflits de routage",
  "task tiers": "niveaux de tâches",
  "Default ({value})": "Par défaut ({value})",
  "Let Auto use paid API models?": "Autoriser Auto à utiliser des modèles API payants ?",
  "Workers in this project may run on providers billed per token, up to the tier you picked. Those turns are billed to the provider's API account at API rates. SpecWithCode cannot read or cap that balance; set a spend limit with the provider.":
    "Les workers de ce projet peuvent s’exécuter sur des fournisseurs facturés au token, jusqu’au niveau choisi. Ces tours sont facturés sur le compte API du fournisseur au tarif API. SpecWithCode ne peut ni lire ni plafonner ce solde ; fixez une limite de dépenses chez le fournisseur.",
  "Workers may run on providers billed per token, up to the tier you picked, in every project that does not override this. Those turns are billed to the provider's API account at API rates. SpecWithCode cannot read or cap that balance; set a spend limit with the provider.":
    "Les workers peuvent s’exécuter sur des fournisseurs facturés au token, jusqu’au niveau choisi, dans tous les projets qui ne remplacent pas ce réglage. Ces tours sont facturés sur le compte API du fournisseur au tarif API. SpecWithCode ne peut ni lire ni plafonner ce solde ; fixez une limite de dépenses chez le fournisseur.",
  "Allow paid API": "Autoriser l’API payante",
