    "Hérité du specweave-studio.json du dépôt",
  "Inherited from {source}": "Hérité de : {source}",
  "Set on the environment": "Défini sur l’environnement",
  "Built-in default": "Valeur par défaut intégrée",
  "Hosts & capacity": "Hôtes et capacité",
