  "Each paragraph or code block appears as soon as it is complete.":
    "Chaque paragraphe ou bloc de code apparaît dès qu’il est complet.",
  "Text appears once the agent finishes its turn.":
    "Le texte apparaît une fois que l’agent a terminé son tour.",
  "Suggest a next prompt after each reply: Claude's own, or one written by the text generation model for other providers. Press Tab to use it.":
    "Suggérer un prochain prompt après chaque réponse : celui de Claude, ou un prompt écrit par le modèle de génération de texte pour les autres fournisseurs. Appuyez sur Tab pour l’utiliser.",
  "Suggest a next prompt only when Claude sends one with its reply. Press Tab to use it.":
    "Suggérer un prochain prompt seulement quand Claude en envoie un avec sa réponse. Appuyez sur Tab pour l’utiliser.",
  "Never suggest a next prompt.": "Ne jamais suggérer de prochain prompt.",
  "Pauses probes for idle clients, locked hosts, or low power mode.":
    "Met en pause les sondages pour les clients inactifs, les hôtes verrouillés ou le mode économie d’énergie.",
  "Allows scoped background probes while any subscribed client remains connected.":
    "Autorise des sondages d’arrière-plan limités tant qu’un client abonné reste connecté.",
  "Also pauses background probes when the host or client is on battery.":
    "Met aussi en pause les sondages d’arrière-plan quand l’hôte ou le client est sur batterie.",
  "Hide thinking, tool runs and in-between messages; one line per turn, opened on click":
    "Masquer la réflexion, les exécutions d’outils et les messages intermédiaires ; une ligne par tour, ouverte au clic",
  "Fold finished turns and tool groups": "Replier les tours terminés et les groupes d’outils",
  "Open every turn, tool call and thought": "Ouvrir chaque tour, appel d’outil et réflexion",
  "In each project, matches recent change descriptions and change request titles.":
    "Dans chaque projet, suit les descriptions de modifications et les titres de demandes de modification récents.",
  "Use Conventional Commit prefixes and keep change request text concise.":
    "Utiliser les préfixes Conventional Commits et garder concis le texte des demandes de modification.",
  "Use your instructions for change descriptions and change requests in every project.":
    "Utiliser vos instructions pour les descriptions de modifications et les demandes de modification dans chaque projet.",
  "Network settings are managed where this server runs.":
    "Les réglages réseau sont gérés là où ce serveur s’exécute.",
  "Bound to this machine. Private HTTPS and SSH tunnels can still provide remote access.":
    "Lié à cette machine. Les tunnels HTTPS privés et SSH peuvent toujours fournir un accès à distance.",
  "Remote connections are enabled. Pairing is required for access.":
    "Les connexions à distance sont activées. L’appairage est requis pour l’accès.",
  "Check the server launch settings for its listener address.":
    "Vérifiez les réglages de lancement du serveur pour son adresse d’écoute.",
  "Automatic capture isn't available here. Choose a window instead.":
    "La capture automatique n’est pas disponible ici. Choisissez plutôt une fenêtre.",
