  "Apps allowed on this machine": "Apps autorisées sur cette machine",
  "No apps allowed on this machine yet. When an agent asks to use an app, choose Always on this machine to stop it asking again.":
    "Aucune app n’est encore autorisée sur cette machine. Quand un agent demande à utiliser une app, choisissez Toujours sur cette machine pour qu’il ne redemande pas.",
  "Devices allowed on this machine": "Appareils autorisés sur cette machine",
  "No devices allowed on this machine yet. When an agent asks to use a device, choose Always on this machine to stop it asking again.":
    "Aucun appareil n’est encore autorisé sur cette machine. Quand un agent demande à utiliser un appareil, choisissez Toujours sur cette machine pour qu’il ne redemande pas.",
  "Enable this environment to open simulators and emulators, whether they run here or on a remote device host.":
    "Permettre à cet environnement d’ouvrir des simulateurs et des émulateurs, qu’ils tournent ici ou sur un hôte d’appareils distant.",
  "Allow new agent sessions in this environment to start and control local and remote devices, with required tools set up automatically.":
    "Permettre aux nouvelles sessions d’agent de cet environnement de démarrer et contrôler des appareils locaux et distants, avec les outils nécessaires configurés automatiquement.",
  "Each AI tool keeps its own MCP list, so a server enabled in Claude Code is not available in Codex until it is added there too.":
    "Chaque outil d’IA garde sa propre liste MCP : un serveur activé dans Claude Code n’est donc pas disponible dans Codex tant qu’il n’y est pas ajouté aussi.",
  "Claude Code loads these only when it runs in that folder. Other folders, projects and providers do not get them. They are stored in your ~/.claude.json.":
    "Claude Code ne les charge que lorsqu’il s’exécute dans ce dossier. Les autres dossiers, projets et fournisseurs ne les reçoivent pas. Ils sont stockés dans votre ~/.claude.json.",
